  c.onkeyup=e=>{if(keyStroke&&(e.key==='Shift'||e.code==='Space'||e.key.startsWith('Arrow')))finish();};c.onblur=()=>{finish();$('#math-cursor').hidden=true;};
  $('#math-select').onclick=()=>modeSet('select');$('#math-draw').onclick=()=>modeSet('draw');$('#math-objects').onchange=e=>{finish();selected=e.target.value||null;render();};$('#math-edit').onclick=selectEdit;$('#math-delete').onclick=()=>{if(live()&&ready&&!busy){finish();doc.remove(selected);changed();}};
